do $$ declare r uuid; x public.rma_requests%rowtype; before_balance numeric; before_stock integer; ledger_count integer; oid uuid; lid uuid; other uuid; cap record; begin
 perform pg_temp.assert_true(not has_function_privilege('anon','public.admin_perform_rma_simple_action_v1(uuid,text,jsonb,text)','EXECUTE'),'anonymous cannot refund');
 perform pg_temp.assert_true(not has_function_privilege('authenticated','private.rma_simple_refund_cap(uuid)','EXECUTE'),'private pricing helper unavailable');
 perform pg_temp.assert_true((select count(*) from public.customer_wallets where customer_id='20000000-0000-4000-8000-000000000001')=1,'customer insert creates exactly one wallet');
 perform pg_temp.assert_true((select balance from public.customer_wallets where customer_id='20000000-0000-4000-8000-000000000001')=0,'new wallet starts at zero');
 r:=pg_temp.make_rma(1,'pending','wallet_credit','submitted');
 x:=public.admin_perform_rma_review_action(r,'approve','Send goods to the shop with safe packaging.',null,'direct-approval');
 perform pg_temp.assert_true(x.status='approved','approve directly from submitted');
 perform pg_temp.assert_true((select count(*) from public.notification_events where rma_request_id=r and source_action='review_status_change')=1,'direct approval emits one notification');
 select * into cap from public.admin_rma_refund_preview_v5(r);
 perform pg_temp.assert_true(cap.available and cap.max_refund_amount=10,'preview before receiving goods');
 select balance into before_balance from public.customer_wallets where customer_id=x.customer_id;
 x:=public.admin_perform_rma_simple_action_v1(r,'execute_refund','{"refund_method":"wallet_credit","refund_amount":8}','wallet-early-refund');
 perform pg_temp.assert_true(x.status='refunded' and x.received_at is null and x.received_quantity is null and x.inventory_disposition='pending','early refund does not fabricate receipt or inventory');
 perform pg_temp.assert_true(x.refund_gross_amount=8 and x.refund_transaction_id is not null,'wallet refund links exact credit');
 perform pg_temp.assert_true((select balance from public.customer_wallets where customer_id=x.customer_id)=before_balance+8,'wallet credited once');
 perform public.admin_perform_rma_simple_action_v1(r,'execute_refund','{"refund_method":"wallet_credit","refund_amount":8}','wallet-early-refund');
 perform pg_temp.assert_true((select count(*) from public.customer_wallet_transactions where metadata->>'rma_request_id'=r::text)=1,'same retry produces one credit');
 perform pg_temp.expect_error(format('select public.admin_perform_rma_simple_action_v1(%L,''execute_refund'',''{"refund_method":"cash","refund_amount":8,"cash_paid":true}'',''wallet-early-refund'')',r),'changed payload with same key fails');
 perform pg_temp.expect_error(format('select public.admin_perform_rma_simple_action_v1(%L,''execute_refund'',''{"refund_method":"cash","refund_amount":8,"cash_paid":true}'',''second-payment'')',r),'different key cannot refund again');
 perform pg_temp.expect_error(format('select public.admin_perform_rma_simple_action_v1(%L,''close'',''{}'',''premature-close'')',r),'cannot close while goods pending');
 x:=public.admin_perform_rma_simple_action_v1(r,'waive_return','{"reason":"Customer may keep the damaged display"}','waive-return-early');
 perform pg_temp.assert_true(x.return_waived_at is not null and x.received_at is null,'waiver does not fake receipt');
 -- Waiver now completes this paid case in its own transaction.
 perform pg_temp.assert_true(x.status='closed','waived return can close');
 r:=pg_temp.make_rma(1,'pending','replacement','approved');
 perform pg_temp.expect_error(format('select public.admin_perform_rma_simple_action_v1(%L,''execute_refund'',''{"refund_method":"cash","refund_amount":10,"cash_paid":true}'',''change-direction'')',r),'replacement change requires confirmation');
 perform pg_temp.expect_error(format('select public.admin_perform_rma_simple_action_v1(%L,''execute_refund'',''{"refund_method":"cash","refund_amount":10,"confirm_resolution_change":true}'',''cash-not-paid'')',r),'cash requires actual payment confirmation');
 select balance into before_balance from public.customer_wallets where customer_id='20000000-0000-4000-8000-000000000001';
 x:=public.admin_perform_rma_simple_action_v1(r,'execute_refund','{"refund_method":"cash","refund_amount":10,"cash_paid":true,"confirm_resolution_change":true}','cash-early-refund');
 perform pg_temp.assert_true(x.refund_method='cash' and x.refund_transaction_id is null,'cash never creates wallet credit');
 perform pg_temp.assert_true((select balance from public.customer_wallets where customer_id=x.customer_id)=before_balance,'cash preserves wallet balance');
 perform pg_temp.assert_true(private.order_wallet_refundable_amount(x.order_id)=0,'cash consumes order refundable limit for legacy and new paths');
 x:=public.admin_perform_rma_simple_action_v1(r,'mark_received','{"quantity":1}','received-after-cash');
 perform pg_temp.assert_true(x.status='refunded' and x.received_quantity=1 and x.inventory_disposition='quarantine','receive after refund preserves financial outcome');
 perform public.admin_perform_rma_action_v4(r,'record_qc','{"qc_status":"failed","qc_note":"Defective panel"}','qc-after-cash');
 perform public.admin_perform_rma_action_v4(r,'mark_scrapped','{"quantity":1,"batch_code":"TEST-RETURN","location":"Milano"}','scrap-after-cash');
 select * into x from public.rma_requests where id=r;
 perform pg_temp.assert_true(x.status='closed' and x.refund_method='cash','cash return closes after real disposition');
 r:=pg_temp.make_rma(1,'failed');
 perform public.admin_perform_rma_action_v4(r,'request_wallet_refund','{"refund_amount":10}','old-wallet-request');
 x:=public.admin_perform_rma_simple_action_v1(r,'execute_refund','{"refund_method":"cash","refund_amount":10,"cash_paid":true}','cash-replaces-pending');
 perform pg_temp.assert_true((select status from public.wallet_refund_requests where id=x.wallet_refund_request_id)='rejected','pending wallet request terminated when cash pays');
 perform pg_temp.expect_error(format('select public.admin_approve_wallet_refund_request(%L,''old approval'')',x.wallet_refund_request_id),'old pending cannot be approved after cash');
 -- Missing historical snapshot is reconstructed from a consistent paid original line.
 r:=pg_temp.make_rma(1,'pending','wallet_credit','approved');
 update public.rma_requests set unit_price_snapshot=null,refund_pricing_snapshot=null,order_line_snapshot='{}' where id=r;
 x:=public.admin_perform_rma_simple_action_v1(r,'execute_refund','{"refund_method":"wallet_credit","refund_amount":10}','historical-pricing');
 perform pg_temp.assert_true(x.unit_price_snapshot=10 and x.refund_pricing_snapshot is not null,'historical original price verified atomically');
 -- Split quantities share one original line and one monetary cap across refund methods.
 r:=pg_temp.make_rma(2,'pending','wallet_credit','approved');
 perform public.admin_perform_rma_action_v4(r,'split_request','{"quantity":1}','split-cash-wallet');
 select id into other from public.rma_requests where parent_request_id=r;
 perform public.admin_perform_rma_simple_action_v1(r,'execute_refund','{"refund_method":"cash","refund_amount":10,"cash_paid":true}','split-cash-payment');
 select * into cap from public.admin_rma_refund_preview_v5(other);
 perform pg_temp.assert_true(cap.available and cap.max_refund_amount=10,'split child sees remaining line balance');
 perform public.admin_perform_rma_simple_action_v1(other,'execute_refund','{"refund_method":"wallet_credit","refund_amount":10}','split-wallet-payment');
 select order_id into oid from public.rma_requests where id=r;
 perform pg_temp.assert_true(private.order_wallet_refundable_amount(oid)=0,'split cash plus wallet cannot exceed original order');
 -- Last returned quantity receives the tax rounding remainder, across cash/wallet.
 r:=pg_temp.make_rma(3,'pending','wallet_credit','approved',0.01);
 perform public.admin_perform_rma_action_v4(r,'split_request','{"quantity":1}','split-tax-one');
 select id into other from public.rma_requests where parent_request_id=r;
 perform public.admin_perform_rma_action_v4(other,'split_request','{"quantity":1}','split-tax-two');
 select id into lid from public.rma_requests where parent_request_id=other;
 perform public.admin_perform_rma_simple_action_v1(r,'execute_refund','{"refund_method":"cash","refund_amount":10,"cash_paid":true}','tax-cash-first');
 perform public.admin_perform_rma_simple_action_v1(other,'execute_refund','{"refund_method":"wallet_credit","refund_amount":10}','tax-wallet-second');
 select * into cap from public.admin_rma_refund_preview_v5(lid);
 perform pg_temp.assert_true(cap.max_refund_amount=10.01,'last split gets remaining tax cent');
 perform public.admin_perform_rma_simple_action_v1(lid,'execute_refund','{"refund_method":"wallet_credit","refund_amount":10.01}','tax-wallet-last');
 select order_id into oid from public.rma_requests where id=r;
 perform pg_temp.assert_true((select sum(refund_tax_amount) from public.rma_requests where order_id=oid)=0.01,'split tax allocation reconciles to original invoice');
 -- A conflicting historic snapshot must not be silently rewritten.
 r:=pg_temp.make_rma(1,'pending','wallet_credit','approved');
 update public.rma_requests set order_line_snapshot=jsonb_build_object('unit_price',99) where id=r;
 perform pg_temp.expect_error(format('select public.admin_perform_rma_simple_action_v1(%L,''execute_refund'',''{"refund_method":"wallet_credit","refund_amount":10}'',''conflicting-history'')',r),'conflicting historical original-price evidence rejected');
 r:=pg_temp.make_rma(1,'pending','wallet_credit','approved');
 perform pg_temp.expect_error(format('select public.admin_perform_rma_simple_action_v1(%L,''execute_refund'',''{"refund_method":"wallet_credit","refund_amount":11}'',''over-cap-amount'')',r),'over-cap amount rejected');
 perform pg_temp.assert_true(not exists(select 1 from public.rma_action_executions where rma_request_id=r and action='execute_refund'),'failed refund fully rolls back execution');
 insert into public.admin_user_permission_overrides(user_id,permission_id,effect) values(auth.uid(),'wallet_refunds.approve','deny');
 perform pg_temp.expect_error(format('select public.admin_perform_rma_simple_action_v1(%L,''execute_refund'',''{"refund_method":"wallet_credit","refund_amount":10}'',''denied-permission'')',r),'manage permission alone cannot pay');
 delete from public.admin_user_permission_overrides where user_id=auth.uid();
 perform set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000002',true);
 perform pg_temp.expect_error(format('select * from public.admin_rma_refund_preview_v5(%L)',r),'customer cannot read another refund preview');
end $$;
rollback;
